-- 085e_wire_generated_imagery_into_content_data.sql
--
-- Points the placements at assets that EXIST. Every path below was probed and
-- returns 200 from the live origin; 21 of the site's 23 planned images were
-- already deployed and only three were referenced anywhere.
--   * hero_url on the pages whose hero carried no image, or carried the
--     guessed /assets/images/hero.jpg that 404s
--   * the four capabilities carousel cards, which rendered broken images
--   * the about people-feature-block
--   * icon_image on all 30 info-card-grid cards, replacing emoji with the
--     generated line-illustration icons the brief asked for
-- Emoji stay in `icon` as the fallback; the template prefers icon_image.

BEGIN;
UPDATE page_components SET content_data = '{"headline": "What this platform can do, and what it''s done", "subheadline": "More than ten production sites run on this platform today. Each one is ours, labelled as ours, and available to inspect. The capabilities described here are demonstrated on real properties — not projected from a slide deck.", "hero_url": "/assets/images/hero-capabilities.jpg"}'::jsonb, updated_at = NOW() WHERE id = '22130f6a-81a1-4c7e-9bee-1ac4150e66b1';  -- capabilities / hero-services
UPDATE page_components SET content_data = '{"cards": [{"image": "/assets/images/hero-review-council.jpg", "title": "A review council that ships decisions", "teaser": "Every change reviewed by a council of agents before it reaches production.", "link_url": "/capabilities.html#review-council", "image_alt": "Line illustration of a structured review process: multiple agent nodes feeding into a single decision document", "link_label": "See how it works"}, {"image": "/assets/images/hero-fine-tuning.jpg", "title": "We caught our own platform fabricating", "teaser": "Our verification system flagged invented details on our own site. We corrected it.", "link_url": "/capabilities.html#verification", "image_alt": "Line illustration of a verification flag catching an error in a published document", "link_label": "Read the audit record"}, {"image": "/assets/images/hero-home.jpg", "title": "A working site in under 24 hours", "teaser": "This platform built and designed this site overnight. The output is visible.", "link_url": "/capabilities.html#rapid-delivery", "image_alt": "Line illustration of a site going live rapidly, represented by a clock alongside a fully assembled page structure", "link_label": "Review the capability"}, {"image": "/assets/images/brand-illustration.jpg", "title": "Private search, built for your data", "teaser": "Production vector search runs on our platform today. A client instance is something we can build.", "link_url": "/capabilities.html#embeddings", "image_alt": "Line illustration of isolated search index blocks connected by a private channel to a client environment", "link_label": "Talk to us"}], "autoplay": false, "section_title": "What this platform demonstrably does", "section_eyebrow": "Capabilities"}'::jsonb, updated_at = NOW() WHERE id = '039ed9d2-5b1f-4e4c-b1d8-16bfc938d4df';  -- capabilities / hero-card-carousel
UPDATE page_components SET content_data = '{"cards": [{"body": "A council of more than a dozen independent agent seats reviews every substantial change. The output is a decision record you can read.", "icon": "🔍", "title": "Multi-agent review before anything ships", "link_url": "/capabilities.html#review-council", "link_label": "See how it works", "icon_image": "/assets/images/icon-cap-review.jpg"}, {"body": "Every review produces a readable, attributable artefact. It records what was checked, what was flagged, and why the change was accepted or rejected.", "icon": "📋", "title": "Decision records, not log entries", "link_url": "/capabilities.html#decision-record", "link_label": "Review the artefact", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "This site was designed and built overnight by the platform itself. Rapid delivery is a demonstrated property, not a promise.", "icon": "⚡", "title": "A working site in under 24 hours", "link_url": "/capabilities.html#rapid-delivery", "link_label": "See the evidence", "icon_image": "/assets/images/icon-cap-delivery.jpg"}, {"body": "We caught our own platform publishing invented details on leopardessconsulting.co.uk. Our verification system flagged it and we corrected it.", "icon": "🛡️", "title": "Verification that catches our own errors", "link_url": "/capabilities.html#verification", "link_label": "Read the case", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "Production vector search runs on our own platform today. A privately isolated instance for a client is something we can build; the technical groundwork is real.", "icon": "🔒", "title": "Private vector search, built for you", "link_url": "/capabilities.html#embeddings", "link_label": "Talk to us", "icon_image": "/assets/images/icon-cap-search.jpg"}, {"body": "More than ten live sites run on this platform, including a live Stripe payment integration on idea.uk selling a real product.", "icon": "🔗", "title": "Production integration, not a prototype", "link_url": "/capabilities.html#production", "link_label": "Explore the platform", "icon_image": "/assets/images/icon-cap-backend.jpg"}], "section_title": "What this platform demonstrably does", "section_eyebrow": "PLATFORM CAPABILITIES", "section_subtitle": "Each capability here is platform-demonstrated or client-delivered. We label the difference plainly so you can evaluate accurately."}'::jsonb, updated_at = NOW() WHERE id = '2a0d895f-fbb2-463a-ace9-d42199da82c8';  -- capabilities / info-card-grid
UPDATE page_components SET content_data = '{"cta_text": "Work through the decision guide", "headline": "Prompting, RAG, or fine-tuning: a decision guide that starts with your actual use case", "hero_url": "/assets/images/hero-capabilities.jpg", "subheadline": "The three approaches solve different problems. Choosing between them isn''t a matter of preference — it follows from what your data looks like, how your system behaves in production, and what failure costs you. This guide works through those questions in order.", "secondary_cta": "Talk to us about your use case", "background_image": "/assets/images/hero.jpg"}'::jsonb, updated_at = NOW() WHERE id = 'c1522e3a-398e-48ba-b607-1ce082e656bd';  -- tool-model-approach-selector-guide / hero
UPDATE page_components SET content_data = '{"headline": "An AI consultancy that runs on its own platform", "subheadline": "More than ten live production sites run on the same platform we''d build for you. The architecture, the review process, the delivery record — all of it is visible and verifiable. We don''t describe our capabilities in the abstract; we point to them.", "hero_url": "/assets/images/hero-about.jpg"}'::jsonb, updated_at = NOW() WHERE id = '61caeda8-3c2b-44d4-83f9-a03a8eb60e72';  -- about / hero-about
UPDATE page_components SET content_data = '{"body": "Every engagement runs through the same platform we use ourselves. There''s no separate ''client version'' with different standards. When we describe a capability, you can check it against our own live sites. That''s not a policy position; it''s just how the work is structured.", "quote": "", "title": "A firm, not a freelancer with a deck", "eyebrow": "HOW WE WORK", "reverse": true, "hero_url": "/assets/images/hero-about.jpg", "link_url": "https://leopardessconsulting.co.uk", "image_alt": "A line illustration of two people working at a shared desk, reviewing documents and a screen together", "link_label": "See the platform in production", "attribution": "", "background_image": "/assets/images/hero-about.jpg", "image": "/assets/images/hero-about.jpg"}'::jsonb, updated_at = NOW() WHERE id = '560a68ea-6b24-4311-90dc-990596f3d5b3';  -- about / people-feature-block
UPDATE page_components SET content_data = '{"cards": [{"body": "The council doesn''t just approve or reject. It writes a decision record — a real artefact you can read, not a log entry.", "icon": "🗂️", "title": "Every decision leaves a record", "link_url": "/multi-agent-review-council.html#decision-record", "link_label": "See the decision record", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "The council runs more than a dozen independent reviewer seats. Each covers a distinct failure mode the others don''t.", "icon": "🔍", "title": "More than a dozen reviewer seats", "link_url": "/multi-agent-review-council.html#reviewer-seats", "link_label": "Review the architecture", "icon_image": "/assets/images/icon-cap-review.jpg"}, {"body": "Our own platform published invented details on leopardessconsulting.co.uk. The verification layer flagged it; we corrected it before it stayed live.", "icon": "⚠️", "title": "Catches fabrication before it ships", "link_url": "/multi-agent-review-council.html#self-correction", "link_label": "Read what happened", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "Every substantial change across more than ten live production sites passes through the council before it ships. It''s not optional.", "icon": "🔁", "title": "Runs on every production change", "link_url": "/multi-agent-review-council.html#production-sites", "link_label": "See the platform scope", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "Each reviewer agent has a fixed remit. One checks factual grounding. Another checks internal consistency. Roles don''t overlap or compete.", "icon": "📋", "title": "Roles assigned, not improvised", "link_url": "/multi-agent-review-council.html#role-design", "link_label": "Explore the role structure", "icon_image": "/assets/images/icon-multi-agent-review.jpg"}, {"body": "If you''re evaluating whether this council design fits your use case, we''re willing to describe it in detail. No sales deck involved.", "icon": "💬", "title": "Talk through what you need", "link_url": "/contact.html", "link_label": "Start a conversation", "icon_image": "/assets/images/icon-service-review-council.jpg"}], "section_title": "A council of reviewers, not a single check", "section_eyebrow": "HOW THE COUNCIL WORKS", "section_subtitle": "Each seat in the review council has a defined role. Together they catch what a single model passes over."}'::jsonb, updated_at = NOW() WHERE id = '0991122d-7bc5-4ba8-a11c-532ad4d865db';  -- multi-agent-review-council / info-card-grid
UPDATE page_components SET content_data = '{"headline": "Talk to us", "subheadline": "We''re a small operation and we read every message ourselves. If you have a specific brief, send it. If you''re still working out whether what we do fits what you need, that''s a reasonable place to start a conversation too.", "hero_url": "/assets/images/hero-contact.jpg"}'::jsonb, updated_at = NOW() WHERE id = '5601bc02-7a25-443c-8a29-b60003df9e9a';  -- contact / hero-contact
UPDATE page_components SET content_data = '{"cta_text": "Read the audit record", "headline": "We caught our own platform generating invented details. Our verification system flagged it. We corrected it.", "hero_url": "/assets/images/brand-illustration.jpg", "subheadline": "The audit record for leopardessconsulting.co.uk shows what happened and what we changed. Self-correction isn''t a design principle we claim — it''s something you can read.", "secondary_cta": "Talk to us", "background_image": "/assets/images/hero.jpg"}'::jsonb, updated_at = NOW() WHERE id = 'e100f94c-b7fc-42a8-a601-dae9cc81390f';  -- self-correction-leopardessconsulting / hero
UPDATE page_components SET content_data = '{"cards": [{"body": "Our platform flagged invented details it had published on leopardessconsulting.co.uk. We corrected them. The audit record exists.", "icon": "🔍", "title": "Self-correction, on the record", "link_url": "/blog/self-correction-leopardessconsulting.html", "link_label": "Read what happened", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "More than a dozen independent reviewer seats evaluate substantial changes before they ship. The output is a decision record, not a timestamp.", "icon": "⚖️", "title": "A review council, not a log", "link_url": "/multi-agent-review-council.html", "link_label": "See how it works", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "More than ten live sites run on this platform today. They''re ours, labelled as ours. We don''t present them as a client roster.", "icon": "🏗️", "title": "Production sites, not prototypes", "link_url": "/capabilities.html", "link_label": "Review the evidence", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "This site was designed and deployed overnight by the platform itself. Speed here is a demonstrated property, not a scheduling promise.", "icon": "⚡", "title": "Built and live within 24 hours", "link_url": "/capabilities.html", "link_label": "See the output", "icon_image": "/assets/images/icon-cap-delivery.jpg"}, {"body": "A Stripe integration on idea.uk sells a £29 product today. That''s a working production environment, not a sandbox demonstration.", "icon": "🔗", "title": "Live payment integration in production", "link_url": "/capabilities.html", "link_label": "Explore the capability", "icon_image": "/assets/images/icon-cap-backend.jpg"}, {"body": "We haven''t dressed our own sites up as client work. If you want to be the first paying client, the capability is real and the track record is clean.", "icon": "📋", "title": "No fabricated client claims", "link_url": "/contact.html", "link_label": "Start a conversation", "icon_image": "/assets/images/icon-honest-verification.jpg"}], "section_title": "What the verification record shows", "section_eyebrow": "PLATFORM EVIDENCE", "section_subtitle": "Each card points to a specific, verifiable property of this platform. These are demonstrated capabilities, not aspirational claims."}'::jsonb, updated_at = NOW() WHERE id = '10c47e3e-4806-4a0b-a023-b8526465799f';  -- self-correction-leopardessconsulting / info-card-grid
UPDATE page_components SET content_data = '{"cards": [{"body": "We train on actual inputs and outputs, not synthetic proxies. The model learns from what your context genuinely requires.", "icon": "🎯", "title": "Fine-Tuning on Real Usage Data", "link_url": "/model-fine-tuning.html", "link_label": "See how we train", "icon_image": "/assets/images/icon-cap-tuning.jpg"}, {"body": "Every fine-tuned model is tested against the baseline. We report results honestly, including where the gain is marginal.", "icon": "🔍", "title": "Evaluation Against Alternatives", "link_url": "/model-fine-tuning.html", "link_label": "Review our evaluation approach", "icon_image": "/assets/images/icon-service-fine-tuning.jpg"}, {"body": "A council of more than a dozen independent reviewer seats assesses each model before it ships. The decision record is real.", "icon": "🏛️", "title": "Review Council Before Deployment", "link_url": "/about.html", "link_label": "See the decision record", "icon_image": "/assets/images/icon-cap-review.jpg"}, {"body": "Production vector search runs on our own platform today. A privately isolated client instance is something we can build for you.", "icon": "🔒", "title": "Private Vector Search Available", "link_url": "/model-fine-tuning.html", "link_label": "Ask about private search", "icon_image": "/assets/images/icon-cap-search.jpg"}, {"body": "Fine-tuned models connect directly into your existing pipeline. We don''t hand over a model file and leave.", "icon": "⚙️", "title": "Integration Into Production Systems", "link_url": "/model-fine-tuning.html", "link_label": "Talk to us", "icon_image": "/assets/images/icon-cap-backend.jpg"}, {"body": "We distinguish what the platform has demonstrated from what we''ve delivered to a paying client. You''ll always know which is which.", "icon": "📋", "title": "Verified Capabilities, Stated Plainly", "link_url": "/about.html", "link_label": "See what we''ve built", "icon_image": "/assets/images/icon-honest-verification.jpg"}], "section_title": "Fine-tuning built on verifiable evidence", "section_eyebrow": "WHAT WE DELIVER", "section_subtitle": "Each stage of the fine-tuning process produces something you can inspect. We build on real data, evaluate honestly, and deploy through a reviewed, documented process."}'::jsonb, updated_at = NOW() WHERE id = '7f04c321-1062-46cf-87fb-fd8741b0408f';  -- model-fine-tuning / info-card-grid
UPDATE page_components SET content_data = '{"cards": [{"body": "Every substantial change passes through a council of more than a dozen independent agent reviewers. The output is a decision record you can read, not a log entry.", "icon": "🔍", "title": "A review council that ships decisions", "link_url": "/multi-agent-review-council.html", "link_label": "See how the council works", "icon_image": "/assets/images/icon-cap-review.jpg"}, {"body": "This site was designed and built overnight by the platform itself. Rapid delivery is a demonstrated property, not a stated target.", "icon": "⚡", "title": "Production sites built in under 24 hours", "icon_image": "/assets/images/icon-cap-delivery.jpg"}, {"body": "Our platform published invented details on leopardessconsulting.co.uk. Our verification system flagged it and we corrected it. The audit record exists.", "icon": "🛡️", "title": "Verification that catches our own errors", "link_url": "/blog/self-correction-leopardessconsulting.html", "link_label": "Read the correction case", "icon_image": "/assets/images/icon-honest-verification.jpg"}, {"body": "A live Stripe integration runs on idea.uk selling a real product today. More than ten production sites run on this platform.", "icon": "🔗", "title": "Live payment and production integration", "icon_image": "/assets/images/icon-cap-backend.jpg"}, {"body": "Production vector search runs on our own platform today. A privately isolated instance for your organisation is something we can build. The technical groundwork exists and works.", "icon": "🗄️", "title": "Private vector search, built for you", "link_url": "/capabilities.html", "link_label": "Review the capability", "icon_image": "/assets/images/icon-cap-search.jpg"}, {"body": "Our own sites demonstrate the platform and are labelled as ours. We don''t present them as a client roster. If you want to be first, the capability is real.", "icon": "📋", "title": "No fabricated client claims", "link_url": "/about.html", "link_label": "Understand our positioning", "icon_image": "/assets/images/icon-honest-verification.jpg"}], "section_title": "What the platform actually delivers", "section_eyebrow": "Platform Capabilities", "section_subtitle": "Six things this platform does, each demonstrated on real properties. Verify them or ask us to walk you through the evidence."}'::jsonb, updated_at = NOW() WHERE id = '540f1bfe-d7da-47b4-be1b-bde43fe4b4ef';  -- index / info-card-grid

COMMIT;
